head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = 'ULDSTF30629.xml';
scwin.regMode;
scwin.gEmpNo = js_emp_no;
scwin.gIsurCd;
scwin.gChrgNm;
scwin.gComAbbrv;
scwin.gChrgTpNm;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

//부모창에서 필요변수 저장
scwin.fn_GetParentValue = function() {
    scwin.regMode = "REG";
    $c.stf.showObj(btn_Del, false);
    scwin.gIsurCd = frame.opener.scwin.gIsurCd;
    scwin.gChrgNm = frame.opener.scwin.gChrgNm;
    scwin.gComAbbrv = frame.opener.scwin.gComAbbrv;
    scwin.gChrgTpNm = frame.opener.scwin.gChrgTpNm;
};



//선택한 정보 값 셋팅
scwin.fn_ReadInfo = function() {
    var url = "/ListedCompany.do?method=selectLngtrmContsvcPrn" + "&inputMessageId=LNGTRM_CONTSVC_PRN_OUT" + "&ISUR_CD=" + scwin.gIsurCd + "&CHRG_NM=" + scwin.gChrgNm + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_lngtrm.DataID = encodeURI(url);
    dts_lngtrm.reset();
};


//초기화
scwin.fn_Init = function() {
    $c.stf.showObj(txb_Seq, false);
    $c.stf.showObj(txb_Isur_Cd, false);
    $c.stf.showObj(txb_Chrg_Nm, true);
    scwin.gComAbbrv = frame.opener.scwin.gComAbbrv;
    scwin.gChrgTpNm = frame.opener.scwin.gChrgTpNm;
    $c.stf.setObjectValue(txb_Com_Abbrv, scwin.gComAbbrv);
    $c.stf.setObjectValue(txb_Chrg_Tp_Nm, scwin.gChrgTpNm);
    if (scwin.regMode == "REG") {
        $c.stf.setObjectValue(txb_Isur_Cd, scwin.gIsurCd);
        $c.stf.setObjectValue(txb_Chrg_Nm, scwin.gChrgNm);
        //setObjectValue(rdo_Lngtrm_Contsvc_Corr_Yn, "Y");		

    } else {
        btn_Save.src = "../img/btn_modify.gif";
        $c.stf.showObj(btn_Del, true);
    }

    // 가우스헤더 셋팅
    dts_procs.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=LNGTRM_CONTSVC_PRN_OUT";
    dts_procs.reset();
    //dts_procs.AddRow();

};






//등록 및 수정 처리
scwin.fn_Procs = function() {
    var vRdo_Lngtrm_Contsvc_Corr_Yn = $c.stf.getObjectValue(rdo_Lngtrm_Contsvc_Corr_Yn);
    var vTxb_Lngtrm_Contsvc_Bas_Yy = $c.stf.getObjectValue(txb_Lngtrm_Contsvc_Bas_Yy);
    var emp_no = scwin.gEmpNo;
    if (vRdo_Lngtrm_Contsvc_Corr_Yn == "") {
        $c.win.alert("장기근속자 해당여부를 선택하십시오.");
        rdo_Lngtrm_Contsvc_Corr_Yn.focus();
        return;
    }
    if (vTxb_Lngtrm_Contsvc_Bas_Yy == "") {
        $c.win.alert("기준년도를 입력하십시오.");
        txb_Lngtrm_Contsvc_Bas_Yy.focus();
        return;
    }
    if (isNaN($c.stf.getObjectValue(txb_Lngtrm_Contsvc_Bas_Yy))) {
        // 숫자가 아니다.
        var msg = $c.stf.getMessageParam("MSG-0910", "기준년도");
        $c.win.alert(msg);
        txb_Lngtrm_Contsvc_Bas_Yy.focus();
        return;
    }
    if ($c.stf.getObjectValue(txb_Lngtrm_Contsvc_Bas_Yy) != "") {
        // 일자 체크
        if ($c.stf.getObjectValue(txb_Lngtrm_Contsvc_Bas_Yy).length < 4) {
            $c.win.alert("기준년도를 올바르게 입력하십시오.");
            txb_Lngtrm_Contsvc_Bas_Yy.focus();
            return;
        }
    }
    if (!$c.stf.checkMaxLength(txa_Contsvc_Bz_Hist_Contn, 2000, "공시담당자 업무이력 비고")) return false;
    dts_procs.insertRow();
    dts_procs.setCellData(1, "ISUR_CD", $c.stf.getObjectValue(txb_Isur_Cd));
    dts_procs.setCellData(1, "LNGTRM_CONTSVC_CORR_YN", $c.stf.getObjectValue(rdo_Lngtrm_Contsvc_Corr_Yn));
    dts_procs.setCellData(1, "CHRG_NM", scwin.gChrgNm);
    dts_procs.setCellData(1, "CONTSVC_BZ_HIST_CONTN", $c.stf.getObjectValue(txa_Contsvc_Bz_Hist_Contn));
    dts_procs.setCellData(1, "LNGTRM_CONTSVC_BAS_YY", $c.stf.getObjectValue(txb_Lngtrm_Contsvc_Bas_Yy));
    dts_procs.setCellData(1, "SEQ", $c.stf.getObjectValue(txb_Seq));
    //20181116
    //getObjectValue(txb_Chrg_Nm)  -> gChrgNm  으로 변경
    //getObjectValue 는 trim 을 하고 있어서 목록의 이름과 맞지 않음으로 인해 변경

    var tmpStr;
    var vMethod;
    if (scwin.regMode == 'REG') {
        tmpStr = "저장 하시겠습니까?";
        vMethod = "insertLngtrmContsvcPrn";
    } else if (scwin.regMode == 'MOD') {
        tmpStr = "수정 하시겠습니까?";
        vMethod = "updateLngtrmContsvcPrn";
    }
    var vAnswer = confirm(tmpStr);
    if (vAnswer == true) {
        trs_lngtrm.Action = "/ListedCompany.do?method=" + vMethod + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&emp_no=" + emp_no;
        trs_lngtrm.KeyName = "toinb_dataid4";
        trs_lngtrm.KeyValue = "JSP(I:pInput1=dts_procs)";
        trs_lngtrm.Post();
    }
};



//삭제
scwin.fn_delete = function() {
    dts_procs.insertRow();
    dts_procs.setCellData(1, "SEQ", $c.stf.getObjectValue(txb_Seq));
    var tmpStr;
    var vMethod;
    vMethod = "deleteLngtrmContsvcPrn";
    tmpStr = "삭제 하시겠습니까?";
    var vAnswer = confirm(tmpStr);
    if (vAnswer == true) {
        trs_lngtrm.Action = "/ListedCompany.do?method=" + vMethod + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_lngtrm.KeyName = "toinb_dataid4";
        trs_lngtrm.KeyValue = "JSP(I:pInput1=dts_procs)";
        trs_lngtrm.Post();
    }
};






// 장기근속자 등록 가능 여부 체크
scwin.fn_checkLngtrmContsvcPrn = function() {
    var vPOS_YN;
    dts_check_lngtrm.DataID = encodeURI("/ListedCompany.do?method=checkLngtrmContsvcPrn&outputMessageId=DUTY_EDU_TP_ADM_CHK_POS_YN_OUT" + "&ISUR_CD=" + scwin.gIsurCd + "&CHRG_NM=" + scwin.gChrgNm);
    dts_check_lngtrm.Reset();
    vPOS_YN = dts_check_lngtrm.getCellData(1, "POS_YN");
    if (vPOS_YN == "N") {
        scwin.regMode = 'MOD';
    } else {
        scwin.regMode = 'REG';
    }
};
scwin.fn_setYear = function() {
    //default 현재년도 
    var ToDay = new Date();
    var yyyy = parseInt(ToDay.getYear(), 10);
    var minYear = '2010';
    var maxYear = yyyy + 10;
    var str = "^전체";
    for (var i = maxYear; i >= minYear; i--) {
        str += "," + i + "%^" + i;
    }
    //alert(str);
    cmb_New_Edu_Complt_Yy.CBData = str;
    var yyyy_etc;
    yyyy_etc = gNewEduCompltYy;
};
scwin.trs_lngtrm_OnSuccess = async function() {
    $c.win.alert("성공적으로 처리 되었습니다.");
    await $c.frame.CloseFrame();
    // 부모창 reload 처리해야함	
    $c.frame.path("../").fn_Search();
};
scwin.trs_lngtrm_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", '장기근속자'));
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_Save_onclick = function() {
    scwin.fn_Procs();
};
scwin.dts_lngtrm_OnLoadCompleted = function(rowcount) {

};
scwin.btn_Del_onclick = function() {
    scwin.fn_delete();
};
scwin.rdo_Lngtrm_Contsvc_Corr_Yn_onclick = function() {

};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_GetParentValue();
    scwin.fn_checkLngtrmContsvcPrn();
    scwin.fn_Init();
    //fn_setYear();


    if (scwin.regMode == 'MOD') {
        scwin.fn_ReadInfo(); //기본정보 불러오기

    }
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_01);
};
